INSERT INTO public.quizzes (id, title, subject, grade, questions, created_by, is_published, description, quiz_type, difficulty_level, time_limit_minutes, passing_score_percentage, total_questions, allow_retakes, show_answers_after_submission, tags, metadata)
SELECT id, title, subject, grade, questions, created_by, is_published, description, quiz_type, difficulty_level, time_limit_minutes, passing_score_percentage, total_questions, allow_retakes, show_answers_after_submission, tags, metadata FROM jsonb_populate_recordset(NULL::public.quizzes, $smartbridge$[{"id":"6a60bf8c-4e11-5371-8717-e3a3af4e46f5","title":"Mathematics · Grade 10 · Term 2: Geometry and functions","subject":"Mathematics","grade":"Grade 10","questions":[{"question":"A triangle has angles 48° and 62°. Find its third angle.","options":["110°","70°","80°","132°"],"correct_index":1,"explanation":"Interior angles total 180°: 180 − 48 − 62 = 70°. State the angle-sum reason in a written solution."},{"question":"Find the midpoint of A(2; 4) and B(8; 10).","options":["(6; 6)","(10; 14)","(5; 7)","(3; 3)"],"correct_index":2,"explanation":"Average the x-coordinates and y-coordinates separately: ((2+8)/2; (4+10)/2)."},{"question":"For f(x) = 2x + 3, what is f(−2)?","options":["7","1","−7","−1"],"correct_index":3,"explanation":"Substitute with brackets: 2(−2)+3 = −4+3 = −1. A negative input does not always give a negative output."},{"question":"Which point lies on y = x²?","options":["(−3; 9)","(−3; −9)","(2; 8)","(0; 1)"],"correct_index":0,"explanation":"Squaring means multiplying a number by itself: (−3)² = 9. The minus sign is inside the brackets."}],"created_by":"SmartBridge FET content team","is_published":true,"description":"Short formative practice: Geometry and functions. Selected CAPS/ATP skills, with explanations. Not a complete term assessment.","quiz_type":"practice","difficulty_level":"medium","time_limit_minutes":12,"passing_score_percentage":50,"total_questions":4,"allow_retakes":true,"show_answers_after_submission":true,"tags":["CAPS","ATP","term-2","formative","math"],"metadata":{"term":2,"focus":"Geometry and functions","language":"en","content_version":"2026-10-21.1","content_origin":"SmartBridge original","curriculum_year":2026,"atp_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=ZX3jJwqKE2E%3d&tabid=3205&portalid=0&mid=10736","caps_url":"https://www.education.gov.za/Portals/0/CD/National%20Curriculum%20Statements%20and%20Vocational/CAPS%20FET%20_%20MATHEMATICS%20_%20GR%2010-12%20_%20Web_1133.pdf","retention_circular_url":"https://www.education.gov.za/Portals/0/Documents/Publications/2026/Circulars/Circular%20S19%20of%202025%20and%20Annexures.pdf","verified_on":"2026-10-21","lesson_path":"/study-packs/math-10","coverage":"Selected topic and skill samples; not exhaustive term coverage or a full examination paper.","moderation_status":"Independent teacher and language moderation pending","term_note":"Revision included where specified by ATP; some Grade 10/11 Term 4 plans introduce new content."}},{"id":"eeec1bd7-856e-589e-9ae5-2c5422c76a0c","title":"Mathematics · Grade 10 · Term 3: Trigonometry, statistics and growth","subject":"Mathematics","grade":"Grade 10","questions":[{"question":"A right triangle has opposite side 3 and hypotenuse 5 for angle θ. What is sin θ?","options":["5/3","3/4","3/5","4/5"],"correct_index":2,"explanation":"Sine is opposite divided by hypotenuse. Identify the sides relative to θ before choosing a ratio."},{"question":"Find the median of 3, 7, 7, 10, 18.","options":["9","10","18","7"],"correct_index":3,"explanation":"The ordered list has five values; the third is the median. The mean would be 9, a different measure."},{"question":"A bag has 3 red and 2 blue counters. One is chosen at random. P(blue) = ?","options":["2/5","3/5","1/2","2/3"],"correct_index":0,"explanation":"There are 2 blue outcomes out of 5 equally likely counters. Probability is favourable outcomes divided by total outcomes."},{"question":"R2 000 earns 8% simple interest each year for 3 years. Find the final amount.","options":["R2 160","R2 480","R2 519.42","R480"],"correct_index":1,"explanation":"Interest = 2 000 × 0.08 × 3 = R480. Add the original R2 000; R480 alone is only the interest."}],"created_by":"SmartBridge FET content team","is_published":true,"description":"Short formative practice: Trigonometry, statistics and growth. Selected CAPS/ATP skills, with explanations. Not a complete term assessment.","quiz_type":"practice","difficulty_level":"medium","time_limit_minutes":12,"passing_score_percentage":50,"total_questions":4,"allow_retakes":true,"show_answers_after_submission":true,"tags":["CAPS","ATP","term-3","formative","math"],"metadata":{"term":3,"focus":"Trigonometry, statistics and growth","language":"en","content_version":"2026-10-21.1","content_origin":"SmartBridge original","curriculum_year":2026,"atp_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=ZX3jJwqKE2E%3d&tabid=3205&portalid=0&mid=10736","caps_url":"https://www.education.gov.za/Portals/0/CD/National%20Curriculum%20Statements%20and%20Vocational/CAPS%20FET%20_%20MATHEMATICS%20_%20GR%2010-12%20_%20Web_1133.pdf","retention_circular_url":"https://www.education.gov.za/Portals/0/Documents/Publications/2026/Circulars/Circular%20S19%20of%202025%20and%20Annexures.pdf","verified_on":"2026-10-21","lesson_path":"/study-packs/math-10","coverage":"Selected topic and skill samples; not exhaustive term coverage or a full examination paper.","moderation_status":"Independent teacher and language moderation pending","term_note":"Revision included where specified by ATP; some Grade 10/11 Term 4 plans introduce new content."}},{"id":"d9fdde46-2a5f-5e36-9640-2ce0929d57ed","title":"Mathematics · Grade 10 · Term 4: Measurement and number-pattern revision","subject":"Mathematics","grade":"Grade 10","questions":[{"question":"A closed cube has side length 4 cm. Find its total surface area.","options":["64 cm²","16 cm²","24 cm²","96 cm²"],"correct_index":3,"explanation":"A cube has six square faces. Surface area = 6 × 4² = 96 cm²; 4³ gives volume instead."},{"question":"Find the nth term of 5, 8, 11, 14, …","options":["3n + 2","5n + 3","3n + 5","2n + 3"],"correct_index":0,"explanation":"The common difference is 3, so use 3n + c. Setting n = 1 gives c = 2. Check n = 2 gives 8."},{"question":"A cylinder has radius 3 cm and height 5 cm. Find its volume in terms of π.","options":["15π cm³","45π cm³","90π cm³","30π cm³"],"correct_index":1,"explanation":"Volume = πr²h = π × 3² × 5. Radius is squared; do not use the diameter as the radius."},{"question":"Expand (x + 4)(x − 2).","options":["x² + 6x − 8","x² + 2x + 8","x² + 2x − 8","x² − 8"],"correct_index":2,"explanation":"Multiply all four pairs: x² − 2x + 4x − 8. Combine the middle terms to get 2x."}],"created_by":"SmartBridge FET content team","is_published":true,"description":"Short formative practice: Measurement and number-pattern revision. Selected CAPS/ATP skills, with explanations. Not a complete term assessment.","quiz_type":"practice","difficulty_level":"medium","time_limit_minutes":12,"passing_score_percentage":50,"total_questions":4,"allow_retakes":true,"show_answers_after_submission":true,"tags":["CAPS","ATP","term-4","formative","math"],"metadata":{"term":4,"focus":"Measurement and number-pattern revision","language":"en","content_version":"2026-10-21.1","content_origin":"SmartBridge original","curriculum_year":2026,"atp_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=ZX3jJwqKE2E%3d&tabid=3205&portalid=0&mid=10736","caps_url":"https://www.education.gov.za/Portals/0/CD/National%20Curriculum%20Statements%20and%20Vocational/CAPS%20FET%20_%20MATHEMATICS%20_%20GR%2010-12%20_%20Web_1133.pdf","retention_circular_url":"https://www.education.gov.za/Portals/0/Documents/Publications/2026/Circulars/Circular%20S19%20of%202025%20and%20Annexures.pdf","verified_on":"2026-10-21","lesson_path":"/study-packs/math-10","coverage":"Selected topic and skill samples; not exhaustive term coverage or a full examination paper.","moderation_status":"Independent teacher and language moderation pending","term_note":"Revision included where specified by ATP; some Grade 10/11 Term 4 plans introduce new content."}},{"id":"0314ec78-0cce-5dca-8e95-359bb8dd252a","title":"Mathematical Literacy · Grade 10 · Term 2: Bills, units, scale and probability","subject":"Mathematical Literacy","grade":"Grade 10","questions":[{"question":"A bill charges R50 fixed plus R2 per kWh. What does 80 kWh cost?","options":["R160","R130","R210","R260"],"correct_index":2,"explanation":"Usage costs 80×R2 = R160. Add the fixed R50 once to get R210. A fixed charge is not multiplied by usage."},{"question":"Convert 2.5 litres to millilitres.","options":["250 mL","25 mL","0.0025 mL","2 500 mL"],"correct_index":3,"explanation":"One litre equals 1 000 millilitres. Multiply 2.5 by 1 000 and keep the unit."},{"question":"On a 1:100 plan, a wall measures 4 cm. Find its real length in metres.","options":["4 m","40 m","0.4 m","400 m"],"correct_index":0,"explanation":"Multiply the drawing length by 100: 400 cm. Divide by 100 to convert centimetres to metres."},{"question":"A spinner has 8 equal sectors; 3 are green. P(green) is…","options":["5/8","3/8","3/5","8/3"],"correct_index":1,"explanation":"Equal sectors give equally likely outcomes: 3 favourable sectors out of 8 total."}],"created_by":"SmartBridge FET content team","is_published":true,"description":"Short formative practice: Bills, units, scale and probability. Selected CAPS/ATP skills, with explanations. Not a complete term assessment.","quiz_type":"practice","difficulty_level":"medium","time_limit_minutes":12,"passing_score_percentage":50,"total_questions":4,"allow_retakes":true,"show_answers_after_submission":true,"tags":["CAPS","ATP","term-2","formative","matlit"],"metadata":{"term":2,"focus":"Bills, units, scale and probability","language":"en","content_version":"2026-10-21.1","content_origin":"SmartBridge original","curriculum_year":2026,"atp_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=68SQP-5M5pk%3d&tabid=3205&portalid=0&mid=10736","caps_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=q8-SkGy43rw%3d&tabid=570&portalid=0&mid=1558","retention_circular_url":"https://www.education.gov.za/Portals/0/Documents/Publications/2026/Circulars/Circular%20S19%20of%202025%20and%20Annexures.pdf","verified_on":"2026-10-21","lesson_path":"/study-packs/matlit-10","coverage":"Selected topic and skill samples; not exhaustive term coverage or a full examination paper.","moderation_status":"Independent teacher and language moderation pending","term_note":"Revision included where specified by ATP; some Grade 10/11 Term 4 plans introduce new content."}},{"id":"f8b573af-fd4e-56d8-8bb6-ec3f08e4f717","title":"Mathematical Literacy · Grade 10 · Term 3: Budgets, interest and floor plans","subject":"Mathematical Literacy","grade":"Grade 10","questions":[{"question":"A learner earns R900 and spends R250 on transport and R400 on food. What remains?","options":["R650","R1 550","R350","R250"],"correct_index":3,"explanation":"Total spending = 250+400 = R650. Remaining money = income−spending = 900−650 = R250."},{"question":"A savings example uses 5% simple annual interest on R1 200 for one year. Find the interest.","options":["R60","R1 260","R600","R6"],"correct_index":0,"explanation":"5% means 0.05. Interest = 1 200×0.05 = R60; R1 260 includes the original savings."},{"question":"A rectangular room is 4 m by 3 m. Find its floor area.","options":["14 m²","12 m²","7 m²","24 m²"],"correct_index":1,"explanation":"Area = length×width = 4×3 = 12 m². 14 m is its perimeter, a length rather than an area."},{"question":"A product costs R80 and sells for R100. What is the profit?","options":["R180","R80","R20","R25"],"correct_index":2,"explanation":"Profit = selling price−cost price = R100−R80 = R20. This is the amount, not a percentage."}],"created_by":"SmartBridge FET content team","is_published":true,"description":"Short formative practice: Budgets, interest and floor plans. Selected CAPS/ATP skills, with explanations. Not a complete term assessment.","quiz_type":"practice","difficulty_level":"medium","time_limit_minutes":12,"passing_score_percentage":50,"total_questions":4,"allow_retakes":true,"show_answers_after_submission":true,"tags":["CAPS","ATP","term-3","formative","matlit"],"metadata":{"term":3,"focus":"Budgets, interest and floor plans","language":"en","content_version":"2026-10-21.1","content_origin":"SmartBridge original","curriculum_year":2026,"atp_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=68SQP-5M5pk%3d&tabid=3205&portalid=0&mid=10736","caps_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=q8-SkGy43rw%3d&tabid=570&portalid=0&mid=1558","retention_circular_url":"https://www.education.gov.za/Portals/0/Documents/Publications/2026/Circulars/Circular%20S19%20of%202025%20and%20Annexures.pdf","verified_on":"2026-10-21","lesson_path":"/study-packs/matlit-10","coverage":"Selected topic and skill samples; not exhaustive term coverage or a full examination paper.","moderation_status":"Independent teacher and language moderation pending","term_note":"Revision included where specified by ATP; some Grade 10/11 Term 4 plans introduce new content."}},{"id":"37001702-8a5b-5fe1-b95e-f7ac6cf5f315","title":"Mathematical Literacy · Grade 10 · Term 4: Data handling and year-end revision","subject":"Mathematical Literacy","grade":"Grade 10","questions":[{"question":"Five taxi fares are R12, R15, R15, R18 and R20. Find the mode.","options":["R15","R16","R20","R12"],"correct_index":0,"explanation":"The mode occurs most often. R15 appears twice; every other fare appears once."},{"question":"A class of 40 learners has 10 who walk to school. What angle represents them in a pie chart?","options":["25°","90°","100°","180°"],"correct_index":1,"explanation":"The fraction is 10/40 = ¼. Multiply by 360° to get 90°. The percentage 25% is not an angle."},{"question":"A bar graph starts its vertical axis at 90 instead of 0. What should you check before comparing bars?","options":["Whether every bar becomes a percentage","Whether the data must be false","Whether the shortened scale exaggerates differences","Whether the units can be ignored"],"correct_index":2,"explanation":"A truncated axis can make small differences look large. Read the scale and values before drawing a conclusion."},{"question":"A class survey asks only the top five achievers about study habits. What is a main limitation?","options":["Five is always the correct sample size","The results prove everyone's habits","Surveys never need a sample","The sample may not represent the whole class"],"correct_index":3,"explanation":"Choosing only high achievers introduces selection bias. Include learners with a range of experiences."}],"created_by":"SmartBridge FET content team","is_published":true,"description":"Short formative practice: Data handling and year-end revision. Selected CAPS/ATP skills, with explanations. Not a complete term assessment.","quiz_type":"practice","difficulty_level":"medium","time_limit_minutes":12,"passing_score_percentage":50,"total_questions":4,"allow_retakes":true,"show_answers_after_submission":true,"tags":["CAPS","ATP","term-4","formative","matlit"],"metadata":{"term":4,"focus":"Data handling and year-end revision","language":"en","content_version":"2026-10-21.1","content_origin":"SmartBridge original","curriculum_year":2026,"atp_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=68SQP-5M5pk%3d&tabid=3205&portalid=0&mid=10736","caps_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=q8-SkGy43rw%3d&tabid=570&portalid=0&mid=1558","retention_circular_url":"https://www.education.gov.za/Portals/0/Documents/Publications/2026/Circulars/Circular%20S19%20of%202025%20and%20Annexures.pdf","verified_on":"2026-10-21","lesson_path":"/study-packs/matlit-10","coverage":"Selected topic and skill samples; not exhaustive term coverage or a full examination paper.","moderation_status":"Independent teacher and language moderation pending","term_note":"Revision included where specified by ATP; some Grade 10/11 Term 4 plans introduce new content."}},{"id":"9d672bbb-8bf3-5299-be5b-6cbcb23e9b59","title":"Physical Sciences · Grade 10 · Term 2: Electric circuits and atomic structure","subject":"Physical Sciences","grade":"Grade 10","questions":[{"question":"A charge of 12 C passes a point in 4 s. Find the current.","options":["48 A","0.33 A","8 A","3 A"],"correct_index":3,"explanation":"Current is charge per unit time: I=Q/Δt=12/4=3 A. Coulombs and seconds are not added."},{"question":"Two resistors of 2 Ω and 4 Ω are in series. Find the equivalent resistance.","options":["6 Ω","1.33 Ω","8 Ω","2 Ω"],"correct_index":0,"explanation":"Series resistances add: R=2+4=6 Ω. The reciprocal formula applies to parallel resistors."},{"question":"A neutral atom has atomic number 11 and mass number 23. How many neutrons does it have?","options":["11","12","23","34"],"correct_index":1,"explanation":"Mass number = protons + neutrons. Atomic number is protons, so neutrons = 23−11=12."},{"question":"Which statement describes isotopes of the same element?","options":["Different proton numbers, same element","Same mass number in every isotope","Same proton number, different neutron number","Different proton and electron numbers by definition"],"correct_index":2,"explanation":"The proton number identifies the element. Isotopes differ in neutrons and therefore in mass number."}],"created_by":"SmartBridge FET content team","is_published":true,"description":"Short formative practice: Electric circuits and atomic structure. Selected CAPS/ATP skills, with explanations. Not a complete term assessment.","quiz_type":"practice","difficulty_level":"medium","time_limit_minutes":12,"passing_score_percentage":50,"total_questions":4,"allow_retakes":true,"show_answers_after_submission":true,"tags":["CAPS","ATP","term-2","formative","phsc"],"metadata":{"term":2,"focus":"Electric circuits and atomic structure","language":"en","content_version":"2026-10-21.1","content_origin":"SmartBridge original","curriculum_year":2026,"atp_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=mQ_5vFi9Voc%3d&tabid=3205&portalid=0&mid=10736","caps_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=uVcOcx728Y8%3d&tabid=570&portalid=0&mid=1558","retention_circular_url":"https://www.education.gov.za/Portals/0/Documents/Publications/2026/Circulars/Circular%20S19%20of%202025%20and%20Annexures.pdf","verified_on":"2026-10-21","lesson_path":"/study-packs/phsc-10","coverage":"Selected topic and skill samples; not exhaustive term coverage or a full examination paper.","moderation_status":"Independent teacher and language moderation pending","term_note":"Revision included where specified by ATP; some Grade 10/11 Term 4 plans introduce new content."}},{"id":"a18ff37c-e056-511f-b9a1-b984ad03d435","title":"Physical Sciences · Grade 10 · Term 3: Motion and chemical equations","subject":"Physical Sciences","grade":"Grade 10","questions":[{"question":"A learner walks 6 m east then 2 m west. Find the displacement.","options":["4 m east","8 m east","4 m west","8 m west"],"correct_index":0,"explanation":"Take east positive: +6−2=+4 m. Total distance is 8 m, but displacement includes direction and endpoints."},{"question":"A car's speed increases from 5 m·s⁻¹ to 17 m·s⁻¹ in 4 s. Find its acceleration.","options":["5.5 m·s⁻²","3 m·s⁻²","48 m·s⁻²","12 m·s⁻²"],"correct_index":1,"explanation":"a=(v−u)/Δt=(17−5)/4=3 m·s⁻². Divide the change in velocity, not the final velocity, by time."},{"question":"An object moves at constant velocity 8 m·s⁻¹ for 6 s. Find its displacement.","options":["14 m","1.33 m","48 m","2 m"],"correct_index":2,"explanation":"At constant velocity, Δx=vΔt=8×6=48 m. Acceleration is zero but displacement need not be zero."},{"question":"Balance H₂ + O₂ → H₂O using the smallest whole-number coefficients.","options":["1, 1, 1","1, 2, 1","2, 2, 1","2, 1, 2"],"correct_index":3,"explanation":"2H₂+O₂→2H₂O has 4 hydrogen and 2 oxygen atoms on both sides. Change coefficients, not chemical subscripts."}],"created_by":"SmartBridge FET content team","is_published":true,"description":"Short formative practice: Motion and chemical equations. Selected CAPS/ATP skills, with explanations. Not a complete term assessment.","quiz_type":"practice","difficulty_level":"medium","time_limit_minutes":12,"passing_score_percentage":50,"total_questions":4,"allow_retakes":true,"show_answers_after_submission":true,"tags":["CAPS","ATP","term-3","formative","phsc"],"metadata":{"term":3,"focus":"Motion and chemical equations","language":"en","content_version":"2026-10-21.1","content_origin":"SmartBridge original","curriculum_year":2026,"atp_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=mQ_5vFi9Voc%3d&tabid=3205&portalid=0&mid=10736","caps_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=uVcOcx728Y8%3d&tabid=570&portalid=0&mid=1558","retention_circular_url":"https://www.education.gov.za/Portals/0/Documents/Publications/2026/Circulars/Circular%20S19%20of%202025%20and%20Annexures.pdf","verified_on":"2026-10-21","lesson_path":"/study-packs/phsc-10","coverage":"Selected topic and skill samples; not exhaustive term coverage or a full examination paper.","moderation_status":"Independent teacher and language moderation pending","term_note":"Revision included where specified by ATP; some Grade 10/11 Term 4 plans introduce new content."}},{"id":"cd1d1447-3db7-5cbf-9c2e-ef310e9dc711","title":"Physical Sciences · Grade 10 · Term 4: Chemical quantities and mechanics revision","subject":"Physical Sciences","grade":"Grade 10","questions":[{"question":"Using M(H₂O) = 18 g·mol⁻¹, how many moles are in 36 g of water?","options":["648 mol","2 mol","0.5 mol","18 mol"],"correct_index":1,"explanation":"n=m/M = 36/18 = 2 mol. Molar mass links a measured mass to amount of substance."},{"question":"How many particles are in 0.5 mol? Use Nₐ = 6.02 × 10²³ mol⁻¹.","options":["1.204 × 10²⁴","6.02 × 10²³","3.01 × 10²³","0.83 × 10⁻²³"],"correct_index":2,"explanation":"N=nNₐ = 0.5×6.02×10²³. Half a mole contains half Avogadro's number of particles."},{"question":"An object starts from rest with constant acceleration 2 m·s⁻² for 3 s. Find its displacement.","options":["6 m","18 m","3 m","9 m"],"correct_index":3,"explanation":"Δx=uΔt+½aΔt²=0+½×2×3²=9 m. Include the square on time."},{"question":"A 2 kg object moves at 3 m·s⁻¹. Find its kinetic energy.","options":["9 J","6 J","18 J","3 J"],"correct_index":0,"explanation":"Eₖ=½mv²=½×2×3²=9 J. Speed is squared, so kinetic energy is not simply mass times speed."}],"created_by":"SmartBridge FET content team","is_published":true,"description":"Short formative practice: Chemical quantities and mechanics revision. Selected CAPS/ATP skills, with explanations. Not a complete term assessment.","quiz_type":"practice","difficulty_level":"medium","time_limit_minutes":12,"passing_score_percentage":50,"total_questions":4,"allow_retakes":true,"show_answers_after_submission":true,"tags":["CAPS","ATP","term-4","formative","phsc"],"metadata":{"term":4,"focus":"Chemical quantities and mechanics revision","language":"en","content_version":"2026-10-21.1","content_origin":"SmartBridge original","curriculum_year":2026,"atp_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=mQ_5vFi9Voc%3d&tabid=3205&portalid=0&mid=10736","caps_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=uVcOcx728Y8%3d&tabid=570&portalid=0&mid=1558","retention_circular_url":"https://www.education.gov.za/Portals/0/Documents/Publications/2026/Circulars/Circular%20S19%20of%202025%20and%20Annexures.pdf","verified_on":"2026-10-21","lesson_path":"/study-packs/phsc-10","coverage":"Selected topic and skill samples; not exhaustive term coverage or a full examination paper.","moderation_status":"Independent teacher and language moderation pending","term_note":"Revision included where specified by ATP; some Grade 10/11 Term 4 plans introduce new content."}},{"id":"727479a2-38e8-50ec-8367-39597c71b44a","title":"Life Sciences · Grade 10 · Term 2: Plant transport and animal circulation","subject":"Life Sciences","grade":"Grade 10","questions":[{"question":"Which tissue transports most water and mineral salts from roots towards leaves?","options":["Xylem","Phloem","Epidermis only","Palisade mesophyll"],"correct_index":0,"explanation":"Xylem vessels provide a transport pathway for water and dissolved minerals. Phloem mainly transports organic nutrients such as sucrose."},{"question":"Why can closing stomata reduce water loss?","options":["It stops all root absorption permanently","It reduces the pathway for water vapour to diffuse out","It increases the number of open pores","It turns water into sugar"],"correct_index":1,"explanation":"Stomata are pores through which water vapour exits. Closing them reduces transpiration, although it can also limit carbon dioxide entry."},{"question":"Which blood vessel carries blood away from the heart?","options":["A vein","A lymph node","An artery","An alveolus"],"correct_index":2,"explanation":"Arteries carry blood away from the heart. Direction defines the vessel; not all arteries carry oxygenated blood."},{"question":"Why is a red blood cell's biconcave shape useful?","options":["It makes the cell a rigid cube","It produces antibodies","It stops oxygen diffusion","It gives a large surface area relative to volume for gas exchange"],"correct_index":3,"explanation":"The shape supports rapid gas exchange over a short diffusion distance. Haemoglobin within the cell binds oxygen."}],"created_by":"SmartBridge FET content team","is_published":true,"description":"Short formative practice: Plant transport and animal circulation. Selected CAPS/ATP skills, with explanations. Not a complete term assessment.","quiz_type":"practice","difficulty_level":"medium","time_limit_minutes":12,"passing_score_percentage":50,"total_questions":4,"allow_retakes":true,"show_answers_after_submission":true,"tags":["CAPS","ATP","term-2","formative","lisc"],"metadata":{"term":2,"focus":"Plant transport and animal circulation","language":"en","content_version":"2026-10-21.1","content_origin":"SmartBridge original","curriculum_year":2026,"atp_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=8hlSLsoZ3b0%3d&tabid=3205&portalid=0&mid=10736","caps_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=_yUNfV0A_8o%3d&tabid=570&portalid=0&mid=1558","retention_circular_url":"https://www.education.gov.za/Portals/0/Documents/Publications/2026/Circulars/Circular%20S19%20of%202025%20and%20Annexures.pdf","verified_on":"2026-10-21","lesson_path":"/study-packs/lisc-10","coverage":"Selected topic and skill samples; not exhaustive term coverage or a full examination paper.","moderation_status":"Independent teacher and language moderation pending","term_note":"Revision included where specified by ATP; some Grade 10/11 Term 4 plans introduce new content."}},{"id":"5c19f666-42db-59f7-b691-4873ffdc571c","title":"Life Sciences · Grade 10 · Term 3: Ecosystems, fossils and classification","subject":"Life Sciences","grade":"Grade 10","questions":[{"question":"In grass → grasshopper → frog, what is the grasshopper?","options":["A producer","A primary consumer","A secondary consumer","A decomposer by definition"],"correct_index":1,"explanation":"Grass is the producer. The grasshopper eats the producer, so it is the primary consumer; the frog is a secondary consumer."},{"question":"Which is an abiotic factor in a pond?","options":["Algae","Fish","Water temperature","Bacteria"],"correct_index":2,"explanation":"Abiotic factors are non-living physical or chemical conditions. Living organisms are biotic factors."},{"question":"Why are fossils useful when studying life's history?","options":["They prove every past organism was preserved","They show all species existed at the same time","They cannot be compared with living organisms","They provide evidence of organisms and environments from the past"],"correct_index":3,"explanation":"The fossil record documents past life and changes through time, but preservation is incomplete and biased towards suitable conditions."},{"question":"Which scientific name is correctly written in plain text?","options":["Homo sapiens","homo Sapiens","HOMO SAPIENS","Homo Sapiens"],"correct_index":0,"explanation":"The genus begins with a capital and the species epithet with lowercase. In formatted writing both are italicised, or separately underlined when handwritten."}],"created_by":"SmartBridge FET content team","is_published":true,"description":"Short formative practice: Ecosystems, fossils and classification. Selected CAPS/ATP skills, with explanations. Not a complete term assessment.","quiz_type":"practice","difficulty_level":"medium","time_limit_minutes":12,"passing_score_percentage":50,"total_questions":4,"allow_retakes":true,"show_answers_after_submission":true,"tags":["CAPS","ATP","term-3","formative","lisc"],"metadata":{"term":3,"focus":"Ecosystems, fossils and classification","language":"en","content_version":"2026-10-21.1","content_origin":"SmartBridge original","curriculum_year":2026,"atp_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=8hlSLsoZ3b0%3d&tabid=3205&portalid=0&mid=10736","caps_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=_yUNfV0A_8o%3d&tabid=570&portalid=0&mid=1558","retention_circular_url":"https://www.education.gov.za/Portals/0/Documents/Publications/2026/Circulars/Circular%20S19%20of%202025%20and%20Annexures.pdf","verified_on":"2026-10-21","lesson_path":"/study-packs/lisc-10","coverage":"Selected topic and skill samples; not exhaustive term coverage or a full examination paper.","moderation_status":"Independent teacher and language moderation pending","term_note":"Revision included where specified by ATP; some Grade 10/11 Term 4 plans introduce new content."}},{"id":"da801b88-f617-5d33-a393-c58793034a9b","title":"Life Sciences · Grade 10 · Term 4: Biodiversity and year-end consolidation","subject":"Life Sciences","grade":"Grade 10","questions":[{"question":"Which group has cells without a membrane-bound nucleus?","options":["Animals","Plants","Bacteria","Fungi"],"correct_index":2,"explanation":"Bacteria are prokaryotes. Their DNA is not enclosed in a membrane-bound nucleus, unlike the eukaryotic groups listed."},{"question":"Why are fungi not classified as plants?","options":["They all move using legs","They all lack cell walls","They are all bacteria","They obtain organic nutrients rather than photosynthesising like green plants"],"correct_index":3,"explanation":"Fungi are heterotrophs and absorb nutrients. Their cell walls typically contain chitin, rather than the cellulose characteristic of plants."},{"question":"Which feature is shared by plants and animals?","options":["Their cells have membrane-bound nuclei","They both have chloroplasts in every cell","They both have cellulose cell walls","They are all unicellular"],"correct_index":0,"explanation":"Plants and animals are eukaryotes with membrane-bound nuclei. Animal cells do not have chloroplasts or cellulose walls."},{"question":"A learner says all microorganisms are harmful. Which correction is best?","options":["Every microorganism causes disease","Many microorganisms are beneficial, including decomposers","Only large organisms recycle nutrients","Bacteria have no ecological role"],"correct_index":1,"explanation":"Many microbes break down organic matter and recycle nutrients; others are useful in food production. Some cause disease, but the claim generalises incorrectly."}],"created_by":"SmartBridge FET content team","is_published":true,"description":"Short formative practice: Biodiversity and year-end consolidation. Selected CAPS/ATP skills, with explanations. Not a complete term assessment.","quiz_type":"practice","difficulty_level":"medium","time_limit_minutes":12,"passing_score_percentage":50,"total_questions":4,"allow_retakes":true,"show_answers_after_submission":true,"tags":["CAPS","ATP","term-4","formative","lisc"],"metadata":{"term":4,"focus":"Biodiversity and year-end consolidation","language":"en","content_version":"2026-10-21.1","content_origin":"SmartBridge original","curriculum_year":2026,"atp_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=8hlSLsoZ3b0%3d&tabid=3205&portalid=0&mid=10736","caps_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=_yUNfV0A_8o%3d&tabid=570&portalid=0&mid=1558","retention_circular_url":"https://www.education.gov.za/Portals/0/Documents/Publications/2026/Circulars/Circular%20S19%20of%202025%20and%20Annexures.pdf","verified_on":"2026-10-21","lesson_path":"/study-packs/lisc-10","coverage":"Selected topic and skill samples; not exhaustive term coverage or a full examination paper.","moderation_status":"Independent teacher and language moderation pending","term_note":"Revision included where specified by ATP; some Grade 10/11 Term 4 plans introduce new content."}},{"id":"d488aa09-3b9e-5163-913e-b69255e3aeba","title":"Accounting · Grade 10 · Term 2: Journals, payroll and adjustments","subject":"Accounting","grade":"Grade 10","questions":[{"question":"A business buys trading stock on credit. Which journal usually records this purchase?","options":["Cash receipts journal","Creditors journal","Debtors journal","Cash payments journal"],"correct_index":1,"explanation":"A credit purchase of stock from a supplier belongs in the creditors journal. No cash moves at purchase, so a cash journal is inappropriate."},{"question":"Gross pay is R6 000 and employee deductions total R800. Find net pay.","options":["R6 800","R800","R5 200","R6 000"],"correct_index":2,"explanation":"Net pay = gross pay−employee deductions = R5 200. Employer contributions are a separate concept."},{"question":"Why compare the debtors control balance with the debtors list total?","options":["To guarantee all customers have paid","To replace supporting documents","To make unpaid debts disappear","To identify differences that need investigation"],"correct_index":3,"explanation":"The control account should reconcile with the total individual debtors' balances. Differences may indicate errors requiring correction."},{"question":"Equipment costing R20 000 depreciates at 10% per year on cost. Find one full year's depreciation.","options":["R2 000","R18 000","R200","R22 000"],"correct_index":0,"explanation":"Depreciation = cost×rate×time = 20 000×0.10×1 = R2 000. R18 000 is the carrying value after this charge."}],"created_by":"SmartBridge FET content team","is_published":true,"description":"Short formative practice: Journals, payroll and adjustments. Selected CAPS/ATP skills, with explanations. Not a complete term assessment.","quiz_type":"practice","difficulty_level":"medium","time_limit_minutes":12,"passing_score_percentage":50,"total_questions":4,"allow_retakes":true,"show_answers_after_submission":true,"tags":["CAPS","ATP","term-2","formative","acc"],"metadata":{"term":2,"focus":"Journals, payroll and adjustments","language":"en","content_version":"2026-10-21.1","content_origin":"SmartBridge original","curriculum_year":2026,"atp_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=xMiwoYjt1vw%3d&tabid=3205&portalid=0&mid=10736","caps_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=IIU4LUlZBFM%3d&tabid=570&portalid=0&mid=1558","retention_circular_url":"https://www.education.gov.za/Portals/0/Documents/Publications/2026/Circulars/Circular%20S19%20of%202025%20and%20Annexures.pdf","verified_on":"2026-10-21","lesson_path":"/study-packs/acc-10","coverage":"Selected topic and skill samples; not exhaustive term coverage or a full examination paper.","moderation_status":"Independent teacher and language moderation pending","term_note":"Revision included where specified by ATP; some Grade 10/11 Term 4 plans introduce new content."}},{"id":"cb7375bf-74a8-5f45-a3d7-cbaaef9fb086","title":"Accounting · Grade 10 · Term 3: Financial statements and indicators","subject":"Accounting","grade":"Grade 10","questions":[{"question":"Sales are R80 000 and cost of sales R50 000. Find gross profit.","options":["R130 000","R50 000","R30 000","R80 000"],"correct_index":2,"explanation":"Gross profit = sales−cost of sales = R30 000. Operating expenses are deducted later when calculating net profit."},{"question":"Gross profit is R30 000 and sales R80 000. Find gross profit as a percentage of sales.","options":["60%","62.5%","266.7%","37.5%"],"correct_index":3,"explanation":"30 000/80 000×100 = 37.5%. A percentage of cost of sales would have a different denominator."},{"question":"Rent of R1 000 is owed for the current year but unpaid at year end. What adjustment is needed?","options":["Increase rent expense and recognise an accrued-expense liability","Decrease rent expense and create an asset","Record no expense until payment","Increase bank immediately"],"correct_index":0,"explanation":"Accrual accounting records the expense in the period incurred. The unpaid amount creates a liability."},{"question":"Current assets total R60 000 and current liabilities R30 000. Find the current ratio.","options":["1:2","2:1","3:1","1:1"],"correct_index":1,"explanation":"Current ratio = current assets/current liabilities = 60 000/30 000 = 2:1. It is one indicator of short-term liquidity, not a guarantee of solvency."}],"created_by":"SmartBridge FET content team","is_published":true,"description":"Short formative practice: Financial statements and indicators. Selected CAPS/ATP skills, with explanations. Not a complete term assessment.","quiz_type":"practice","difficulty_level":"medium","time_limit_minutes":12,"passing_score_percentage":50,"total_questions":4,"allow_retakes":true,"show_answers_after_submission":true,"tags":["CAPS","ATP","term-3","formative","acc"],"metadata":{"term":3,"focus":"Financial statements and indicators","language":"en","content_version":"2026-10-21.1","content_origin":"SmartBridge original","curriculum_year":2026,"atp_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=xMiwoYjt1vw%3d&tabid=3205&portalid=0&mid=10736","caps_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=IIU4LUlZBFM%3d&tabid=570&portalid=0&mid=1558","retention_circular_url":"https://www.education.gov.za/Portals/0/Documents/Publications/2026/Circulars/Circular%20S19%20of%202025%20and%20Annexures.pdf","verified_on":"2026-10-21","lesson_path":"/study-packs/acc-10","coverage":"Selected topic and skill samples; not exhaustive term coverage or a full examination paper.","moderation_status":"Independent teacher and language moderation pending","term_note":"Revision included where specified by ATP; some Grade 10/11 Term 4 plans introduce new content."}},{"id":"48a472b9-e6ca-5f9e-a841-b4db6c3b6807","title":"Accounting · Grade 10 · Term 4: Manufacturing costs and budgets","subject":"Accounting","grade":"Grade 10","questions":[{"question":"Which cost is usually direct material for a furniture manufacturer?","options":["Office receptionist's salary","Factory insurance","Advertising for the whole business","Timber used in the chairs"],"correct_index":3,"explanation":"Direct materials can be traced to the product. Timber becomes part of each chair; administration and advertising are not direct materials."},{"question":"Direct materials cost R8 000 and direct labour R5 000. Find prime cost.","options":["R13 000","R3 000","R40 000","R8 000"],"correct_index":0,"explanation":"Prime cost = direct materials + direct labour = R13 000. Factory overheads are added separately for total production cost."},{"question":"A cash budget opens with R4 000, receives R9 000 and pays R10 000. Find its closing balance.","options":["R5 000","R3 000","R23 000","−R1 000"],"correct_index":1,"explanation":"Closing cash = opening cash+receipts−payments = 4 000+9 000−10 000 = R3 000. Opening cash must be included."},{"question":"Which item is excluded from cash payments in a cash budget?","options":["Wages paid","Rent paid","Depreciation","Cash purchase of equipment"],"correct_index":2,"explanation":"Depreciation is a non-cash expense. Equipment purchased for cash is a cash payment even though it is a capital item."}],"created_by":"SmartBridge FET content team","is_published":true,"description":"Short formative practice: Manufacturing costs and budgets. Selected CAPS/ATP skills, with explanations. Not a complete term assessment.","quiz_type":"practice","difficulty_level":"medium","time_limit_minutes":12,"passing_score_percentage":50,"total_questions":4,"allow_retakes":true,"show_answers_after_submission":true,"tags":["CAPS","ATP","term-4","formative","acc"],"metadata":{"term":4,"focus":"Manufacturing costs and budgets","language":"en","content_version":"2026-10-21.1","content_origin":"SmartBridge original","curriculum_year":2026,"atp_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=xMiwoYjt1vw%3d&tabid=3205&portalid=0&mid=10736","caps_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=IIU4LUlZBFM%3d&tabid=570&portalid=0&mid=1558","retention_circular_url":"https://www.education.gov.za/Portals/0/Documents/Publications/2026/Circulars/Circular%20S19%20of%202025%20and%20Annexures.pdf","verified_on":"2026-10-21","lesson_path":"/study-packs/acc-10","coverage":"Selected topic and skill samples; not exhaustive term coverage or a full examination paper.","moderation_status":"Independent teacher and language moderation pending","term_note":"Revision included where specified by ATP; some Grade 10/11 Term 4 plans introduce new content."}}]$smartbridge$::jsonb)
